import java.util.*;
import java.io.*;

public class Main {
    static int n, b, i, j, k, temp, count;
    static int[] arr, dp;
    static int oddCount, evenCount;
    static int maxIndex;

    public static void main(String[] args) throws IOException {
        n = ni();
        b = ni();
        arr = nia(n);
        dp = new int[n];
        oddCount = 0;
        evenCount = 0;
        maxIndex = 0;
        j = 0;

        for (i = 0; i < n - 1; i++) {
            if (arr[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount) {
                dp[j] = Math.abs(arr[i + 1] - arr[i]);
                j++;
            }
        }

        if (j > 0) {
            Arrays.sort(dp, 0, j);
            for (i = 1; i < j; i++) {
                dp[i] += dp[i - 1];
                if (dp[i] <= b) {
                    maxIndex = i;
                }
            }
        }

        System.out.println(maxIndex);
    }

    static int modulo(int x, int m) {
        if (x < 0) return m + x;
        if (x >= m) return x - m;
        return x;
    }

    static final int MOD = 1000000007;
    static final double EPS = 1e-8;
    static final long INF = 100000000000000000L;
    static final boolean DEBUG = true;
    static final Reader reader = new Reader();
    static final StringBuilder output = new StringBuilder();

    static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static final Random rand = new Random();

    static void println(Object obj) { System.out.println(obj); }

    static int ni() { return reader.nextInt(); }
    static int[] nia(int size) { int[] a = new int[size]; for (int idx = 0; idx < size; idx++) a[idx] = ni(); return a; }
    static long nl() { return reader.nextLong(); }
    static long[] nla(int size) { long[] a = new long[size]; for (int idx = 0; idx < size; idx++) a[idx] = nl(); return a; }
    static String ns() { return reader.next(); }
    static String[] nsa(int size) { String[] a = new String[size]; for (int idx = 0; idx < size; idx++) a[idx] = ns(); return a; }
    static double nd() { return reader.nextDouble(); }
    static double[] nda(int size) { double[] a = new double[size]; for (int idx = 0; idx < size; idx++) a[idx] = nd(); return a; }

    static class Reader {
        private final BufferedReader br;
        private StringTokenizer st;

        public Reader() {
            br = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        public int nextInt() { return Integer.parseInt(nextToken()); }
        public long nextLong() { return Long.parseLong(nextToken()); }
        public double nextDouble() { return Double.parseDouble(nextToken()); }
        public String next() {
            try { return nextToken(); } catch (IOException e) { throw new RuntimeException(e); }
        }
    }
